package com.example.todolist.controller;

import com.example.todolist.dto.TaskRequestDTO;import com.example.todolist.enums.TaskStatus;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:testdb;MODE=MySQL;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop"}) @AutoConfigureMockMvc @ActiveProfiles("test")
class TaskControllerIntegrationTest { @Autowired MockMvc mvc; @Autowired ObjectMapper mapper; @Test void shouldCreateAndListTasks() throws Exception { var json=mapper.writeValueAsString(new TaskRequestDTO("Task","Description", TaskStatus.PENDING)); mvc.perform(post("/tasks").contentType(MediaType.APPLICATION_JSON).content(json)).andExpect(status().isCreated()).andExpect(jsonPath("$.id").exists()); mvc.perform(get("/tasks")).andExpect(status().isOk()).andExpect(jsonPath("$.content").isArray()); }}
